{
  "name": "Rapper Card Forge",
  "description": "A trading card generator for a hip-hop themed game. Create, customize, and generate rapper cards with AI-powered tools."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum CardRarity {
  COMMON = 'COMMON',
  SILVER = 'SILVER',
  GOLD = 'GOLD',
  DIAMOND = 'DIAMOND'
}

export interface CardStats {
  ovr: number;
  lyricism: number;
  flow: number;
  speed: number;
  charisma: number;
  defense: number;
}

export interface SuperPower {
  id: string;
  name: string;
  iconUrl: string; // Could be a local path or data URL
}

export interface RapperCardData {
  name: string;
  rarity: CardRarity;
  stats: CardStats;
  image: string | null; // Base64 or URL
  imagePosition: { x: number; y: number; scale: number };
  superpowers: SuperPower[];
}

export type AspectRatio = "1:1" | "3:4" | "4:3" | "9:16" | "16:9" | "2:3" | "3:2" | "21:9";
export type ImageSize = "1K" | "2K" | "4K";

import { GoogleGenAI, Type } from "@google/genai";
import { AspectRatio, ImageSize } from "../types";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

/**
 * Generates an image using Gemini 3 Pro Image Preview.
 */
export const generateRapperImage = async (
  prompt: string,
  aspectRatio: AspectRatio = "1:1",
  imageSize: ImageSize = "1K"
): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [{ text: prompt }]
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
          imageSize: imageSize
        }
      }
    });

    // Extract image from response
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image generated.");
  } catch (error) {
    console.error("Gemini Generate Image Error:", error);
    throw error;
  }
};

/**
 * Edits an existing image using Gemini 2.5 Flash Image.
 * Useful for "Remove background", "Add filter", etc.
 */
export const editRapperImage = async (
  base64Image: string,
  prompt: string
): Promise<string> => {
  try {
    // Strip prefix if present for the API call
    const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, '');

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/png', // Assuming PNG for simplicity, usually safe for inputs
              data: cleanBase64
            }
          },
          { text: prompt }
        ]
      }
    });

     for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No edited image returned.");
  } catch (error) {
    console.error("Gemini Edit Image Error:", error);
    throw error;
  }
};

/**
 * Analyzes an image using Gemini 3 Pro Preview.
 */
export const analyzeRapperImage = async (
  base64Image: string,
  prompt: string = "Analyze this image and suggest stats for a rap battle card (Lyricism, Flow, Speed, Charisma) based on the visual vibe. Output JSON."
): Promise<string> => {
  try {
    const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, '');

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/png',
              data: cleanBase64
            }
          },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
         // We could add a schema here for strict stats parsing, but freeform text/json is requested generally
      }
    });

    return response.text || "{}";
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

import React, { useEffect, useRef, forwardRef, useImperativeHandle } from 'react';
import { CardRarity, RapperCardData } from '../types';

interface CardCanvasProps {
  data: RapperCardData;
  width?: number;
  height?: number;
}

export interface CardCanvasHandle {
  download: () => void;
}

const CardCanvas = forwardRef<CardCanvasHandle, CardCanvasProps>(({ data, width = 400, height = 600 }, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawCard = async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear canvas
    ctx.clearRect(0, 0, width, height);

    // 1. Draw Background (Card Base)
    // In a real app, these would be loaded assets. We will simulate with gradients.
    const gradient = ctx.createLinearGradient(0, 0, width, height);
    switch (data.rarity) {
      case CardRarity.GOLD:
        gradient.addColorStop(0, '#DAA520');
        gradient.addColorStop(0.5, '#FFD700');
        gradient.addColorStop(1, '#B8860B');
        break;
      case CardRarity.SILVER:
        gradient.addColorStop(0, '#C0C0C0');
        gradient.addColorStop(0.5, '#E0E0E0');
        gradient.addColorStop(1, '#A9A9A9');
        break;
      case CardRarity.DIAMOND:
        gradient.addColorStop(0, '#b9f2ff');
        gradient.addColorStop(0.5, '#ffffff');
        gradient.addColorStop(1, '#00d2ff');
        break;
      default: // COMMON
        gradient.addColorStop(0, '#444');
        gradient.addColorStop(1, '#222');
    }

    // Card Border/Frame
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);

    // Inner Frame
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(15, 15, width - 30, height - 30);

    // 2. Draw Rapper Image
    // Use a clipping mask for the image area
    ctx.save();
    ctx.beginPath();
    // Define the image window area
    ctx.rect(25, 60, width - 50, height * 0.55); 
    ctx.clip();

    if (data.image) {
      const img = new Image();
      img.src = data.image;
      await new Promise((resolve) => {
        img.onload = resolve;
        img.onerror = resolve; // Continue even if fail
      });

      // Apply transform
      const { x, y, scale } = data.imagePosition;
      const imgW = img.naturalWidth * scale;
      const imgH = img.naturalHeight * scale;

      // Center + Offset
      const centerX = width / 2 + x;
      const centerY = (60 + (height * 0.55) / 2) + y;

      ctx.drawImage(img, centerX - imgW / 2, centerY - imgH / 2, imgW, imgH);
    } else {
      ctx.fillStyle = '#333';
      ctx.fillRect(25, 60, width - 50, height * 0.55);
      ctx.fillStyle = '#555';
      ctx.font = '20px Arial';
      ctx.textAlign = 'center';
      ctx.fillText("No Image", width / 2, 200);
    }
    ctx.restore();

    // 3. Draw Overlays (Decorations)
    ctx.strokeStyle = data.rarity === CardRarity.COMMON ? '#fff' : gradient;
    ctx.lineWidth = 4;
    ctx.strokeRect(25, 60, width - 50, height * 0.55);

    // 4. Draw Stats & Text
    // Name Plate
    ctx.fillStyle = '#000';
    ctx.fillRect(25, height * 0.68, width - 50, 40);

    ctx.fillStyle = '#fff';
    ctx.font = 'bold 28px Oswald';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(data.name.toUpperCase(), width / 2, height * 0.68 + 22);

    // OVR Badge (Top Left)
    ctx.beginPath();
    ctx.arc(60, 60, 35, 0, Math.PI * 2);
    ctx.fillStyle = data.rarity === CardRarity.GOLD ? '#DAA520' : '#000';
    ctx.fill();
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#fff';
    ctx.stroke();

    ctx.fillStyle = '#fff';
    ctx.font = 'bold 28px Oswald';
    ctx.fillText(data.stats.ovr.toString(), 60, 62);
    ctx.font = '12px Arial';
    ctx.fillText("OVR", 60, 80);

    // Stats Grid (Bottom)
    const statsY = height * 0.78;
    ctx.font = 'bold 16px Inter';
    ctx.textAlign = 'left';

    const drawStat = (label: string, val: number, cX: number, cY: number) => {
        ctx.fillStyle = '#aaa';
        ctx.fillText(label, cX, cY);
        ctx.fillStyle = '#fff';
        ctx.fillText(val.toString(), cX + 50, cY);
    };

    const leftColX = 50;
    const rightColX = width / 2 + 20;

    drawStat("LYRC", data.stats.lyricism, leftColX, statsY);
    drawStat("FLOW", data.stats.flow, leftColX, statsY + 25);
    drawStat("SPED", data.stats.speed, leftColX, statsY + 50);

    drawStat("CHAR", data.stats.charisma, rightColX, statsY);
    drawStat("DEFN", data.stats.defense, rightColX, statsY + 25);

    // Superpowers (Icons)
    if (data.superpowers.length > 0) {
        // Draw small circles at bottom
        data.superpowers.forEach((power, idx) => {
            const px = width - 40 - (idx * 35);
            const py = height - 35;

            ctx.beginPath();
            ctx.arc(px, py, 15, 0, Math.PI * 2);
            ctx.fillStyle = '#4ade80'; // Green for power
            ctx.fill();

            ctx.font = '10px Arial';
            ctx.fillStyle = '#000';
            ctx.textAlign = 'center';
            ctx.fillText(power.name.substring(0,1), px, py + 4);
        });
    }
  };

  useEffect(() => {
    drawCard();
  }, [data, width, height]);

  useImperativeHandle(ref, () => ({
    download: () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const link = document.createElement('a');
      link.download = `${data.name.replace(/\s+/g, '_')}_card.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
  }));

  return (
    <div className="relative shadow-2xl rounded-lg overflow-hidden border border-gray-700">
      <canvas 
        ref={canvasRef} 
        width={width} 
        height={height} 
        className="bg-transparent"
      />
    </div>
  );
});

CardCanvas.displayName = 'CardCanvas';

export default CardCanvas;

import React, { useState, useRef, ChangeEvent } from 'react';
import { 
  Download, 
  Upload, 
  Sparkles, 
  Wand2, 
  ScanEye, 
  Palette, 
  Move,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';
import CardCanvas, { CardCanvasHandle } from './components/CardCanvas';
import { 
  RapperCardData, 
  CardRarity, 
  AspectRatio, 
  ImageSize, 
  CardStats 
} from './types';
import { 
  generateRapperImage, 
  editRapperImage, 
  analyzeRapperImage 
} from './services/geminiService';

const INITIAL_STATS: CardStats = {
  ovr: 85,
  lyricism: 80,
  flow: 88,
  speed: 90,
  charisma: 75,
  defense: 60
};

const INITIAL_DATA: RapperCardData = {
  name: "MC Unknown",
  rarity: CardRarity.COMMON,
  stats: INITIAL_STATS,
  image: null,
  imagePosition: { x: 0, y: 0, scale: 1 },
  superpowers: []
};

export default function App() {
  const [cardData, setCardData] = useState<RapperCardData>(INITIAL_DATA);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<'edit' | 'generate' | 'analyze'>('generate');

  // Gemini Inputs
  const [genPrompt, setGenPrompt] = useState("A futuristic cyberpunk rapper with neon dreadlocks, wearing a golden jacket");
  const [genAspectRatio, setGenAspectRatio] = useState<AspectRatio>("1:1");
  const [genSize, setGenSize] = useState<ImageSize>("1K");

  const [editPrompt, setEditPrompt] = useState("Remove the background and add a purple aura");

  const canvasRef = useRef<CardCanvasHandle>(null);

  // Handlers
  const handleInputChange = (field: keyof RapperCardData, value: any) => {
    setCardData(prev => ({ ...prev, [field]: value }));
  };

  const handleStatChange = (stat: keyof CardStats, value: number) => {
    setCardData(prev => ({
      ...prev,
      stats: { ...prev.stats, [stat]: value }
    }));
  };

  const handleImageUpload = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          handleInputChange('image', event.target.result as string);
          // Reset position on new image
          setCardData(prev => ({ ...prev, imagePosition: { x: 0, y: 0, scale: 1 } }));
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateImage = async () => {
    setIsProcessing(true);
    try {
      const b64 = await generateRapperImage(genPrompt, genAspectRatio, genSize);
      handleInputChange('image', b64);
    } catch (e) {
      alert("Failed to generate image. Check console for details.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleEditImage = async () => {
    if (!cardData.image) {
      alert("Upload or generate an image first!");
      return;
    }
    setIsProcessing(true);
    try {
      const b64 = await editRapperImage(cardData.image, editPrompt);
      handleInputChange('image', b64);
    } catch (e) {
      alert("Failed to edit image.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAnalyzeImage = async () => {
    if (!cardData.image) {
      alert("Upload or generate an image first!");
      return;
    }
    setIsProcessing(true);
    try {
      const jsonStr = await analyzeRapperImage(cardData.image);
      // Clean JSON string
      const cleanJson = jsonStr.replace(/```json|```/g, '').trim();
      const analysis = JSON.parse(cleanJson);

      // Attempt to map analysis to stats if the AI followed instructions
      if (analysis.stats || analysis.lyricism) {
        // Simplified mapping logic
        const newStats = { ...cardData.stats };
        // Very basic key matching
        Object.keys(analysis).forEach(k => {
            const key = k.toLowerCase();
            if (key.includes('lyr')) newStats.lyricism = Number(analysis[k]) || 80;
            if (key.includes('flow')) newStats.flow = Number(analysis[k]) || 80;
            if (key.includes('speed')) newStats.speed = Number(analysis[k]) || 80;
            if (key.includes('char')) newStats.charisma = Number(analysis[k]) || 80;
        });
        setCardData(prev => ({ ...prev, stats: newStats }));
      } else {
        alert("Analysis Complete: " + JSON.stringify(analysis, null, 2));
      }
    } catch (e) {
      alert("Analysis failed or returned invalid JSON.");
    } finally {
      setIsProcessing(false);
    }
  };

  const adjustPosition = (dx: number, dy: number, dScale: number) => {
    setCardData(prev => ({
      ...prev,
      imagePosition: {
        x: prev.imagePosition.x + dx,
        y: prev.imagePosition.y + dy,
        scale: Math.max(0.1, prev.imagePosition.scale + dScale)
      }
    }));
  };

  return (
    <div className="min-h-screen bg-neutral-900 text-gray-100 p-4 md:p-8">
      <header className="max-w-7xl mx-auto mb-8 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="bg-gradient-to-tr from-yellow-500 to-amber-700 p-2 rounded-lg">
            <Palette className="w-8 h-8 text-white" />
          </div>
          <div>
            <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-yellow-400 to-amber-600">
              RAPPER CARD FORGE
            </h1>
            <p className="text-gray-400 text-sm">Create Legendary Trading Cards</p>
          </div>
        </div>
        <button 
          onClick={() => canvasRef.current?.download()}
          className="flex items-center gap-2 bg-green-600 hover:bg-green-700 px-6 py-3 rounded-full font-bold transition-all shadow-lg hover:shadow-green-500/20"
        >
          <Download className="w-5 h-5" />
          Download Card
        </button>
      </header>

      <main className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* LEFT COLUMN: Controls */}
        <div className="lg:col-span-7 space-y-6">

          {/* 1. Card Identity */}
          <section className="bg-neutral-800 p-6 rounded-xl border border-neutral-700">
            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
              <span className="text-yellow-500">01.</span> Identity & Base
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm text-gray-400 mb-1">Rapper Name</label>
                <input 
                  type="text" 
                  value={cardData.name}
                  onChange={(e) => handleInputChange('name', e.target.value)}
                  className="w-full bg-neutral-900 border border-neutral-700 rounded p-2 focus:border-yellow-500 outline-none transition-colors"
                />
              </div>
              <div>
                <label className="block text-sm text-gray-400 mb-1">Rarity</label>
                <select 
                  value={cardData.rarity}
                  onChange={(e) => handleInputChange('rarity', e.target.value)}
                  className="w-full bg-neutral-900 border border-neutral-700 rounded p-2 outline-none"
                >
                  {Object.values(CardRarity).map(r => (
                    <option key={r} value={r}>{r}</option>
                  ))}
                </select>
              </div>
            </div>
          </section>

          {/* 2. AI & Image Tools */}
          <section className="bg-neutral-800 p-6 rounded-xl border border-neutral-700">
            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
              <span className="text-blue-500">02.</span> Visual Studio
            </h2>

            <div className="flex gap-2 mb-4 bg-neutral-900 p-1 rounded-lg w-fit">
              <button 
                onClick={() => setActiveTab('generate')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'generate' ? 'bg-neutral-700 text-white' : 'text-gray-400 hover:text-white'}`}
              >
                <Sparkles className="w-4 h-4" /> Generate
              </button>
              <button 
                onClick={() => setActiveTab('edit')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'edit' ? 'bg-neutral-700 text-white' : 'text-gray-400 hover:text-white'}`}
              >
                <Wand2 className="w-4 h-4" /> Magic Edit
              </button>
              <button 
                onClick={() => setActiveTab('analyze')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'analyze' ? 'bg-neutral-700 text-white' : 'text-gray-400 hover:text-white'}`}
              >
                <ScanEye className="w-4 h-4" /> Analyze
              </button>
            </div>

            <div className="space-y-4">
              {activeTab === 'generate' && (
                <div className="space-y-4 animate-fadeIn">
                  <textarea 
                    value={genPrompt}
                    onChange={(e) => setGenPrompt(e.target.value)}
                    className="w-full bg-neutral-900 border border-neutral-700 rounded p-3 h-24 resize-none focus:border-blue-500 outline-none"
                    placeholder="Describe your rapper..."
                  />
                  <div className="flex gap-4">
                    <div className="flex-1">
                       <label className="block text-xs text-gray-500 mb-1">Aspect Ratio</label>
                       <select value={genAspectRatio} onChange={e => setGenAspectRatio(e.target.value as AspectRatio)} className="w-full bg-neutral-900 border border-neutral-700 p-2 rounded">
                         <option value="1:1">1:1 (Square)</option>
                         <option value="3:4">3:4</option>
                         <option value="4:3">4:3</option>
                         <option value="9:16">9:16</option>
                         <option value="16:9">16:9</option>
                         <option value="21:9">21:9</option>
                       </select>
                    </div>
                    <div className="flex-1">
                       <label className="block text-xs text-gray-500 mb-1">Quality</label>
                       <select value={genSize} onChange={e => setGenSize(e.target.value as ImageSize)} className="w-full bg-neutral-900 border border-neutral-700 p-2 rounded">
                         <option value="1K">1K</option>
                         <option value="2K">2K</option>
                         <option value="4K">4K</option>
                       </select>
                    </div>
                  </div>
                  <button 
                    onClick={handleGenerateImage}
                    disabled={isProcessing}
                    className="w-full bg-blue-600 hover:bg-blue-700 text-white py-2 rounded font-bold disabled:opacity-50"
                  >
                    {isProcessing ? "Generating..." : "Generate Rapper (Gemini Pro)"}
                  </button>
                </div>
              )}

              {activeTab === 'edit' && (
                <div className="space-y-4 animate-fadeIn">
                   <p className="text-sm text-gray-400 flex items-center gap-2">
                     <AlertCircle className="w-4 h-4" />
                     Edit current card image (e.g., "Remove background", "Make it black and white")
                   </p>
                   <textarea 
                    value={editPrompt}
                    onChange={(e) => setEditPrompt(e.target.value)}
                    className="w-full bg-neutral-900 border border-neutral-700 rounded p-3 h-24 resize-none focus:border-purple-500 outline-none"
                  />
                  <button 
                    onClick={handleEditImage}
                    disabled={isProcessing}
                    className="w-full bg-purple-600 hover:bg-purple-700 text-white py-2 rounded font-bold disabled:opacity-50"
                  >
                    {isProcessing ? "Processing..." : "Apply Magic Edit (Gemini Flash)"}
                  </button>
                </div>
              )}

              {activeTab === 'analyze' && (
                <div className="space-y-4 animate-fadeIn">
                  <p className="text-sm text-gray-400">
                    Use Gemini Vision to analyze the current image and suggest stats.
                  </p>
                   <button 
                    onClick={handleAnalyzeImage}
                    disabled={isProcessing}
                    className="w-full bg-teal-600 hover:bg-teal-700 text-white py-2 rounded font-bold disabled:opacity-50"
                  >
                    {isProcessing ? "Analyzing..." : "Analyze Image for Stats"}
                  </button>
                </div>
              )}

              <div className="border-t border-neutral-700 pt-4">
                 <label className="flex items-center gap-2 cursor-pointer bg-neutral-900 hover:bg-neutral-800 p-3 rounded transition-colors justify-center border border-dashed border-gray-600">
                    <Upload className="w-5 h-5" />
                    <span className="text-sm">Or Upload your own PNG</span>
                    <input type="file" accept="image/*" onChange={handleImageUpload} className="hidden" />
                 </label>
              </div>
            </div>
          </section>

          {/* 3. Positioning Controls */}
          <section className="bg-neutral-800 p-6 rounded-xl border border-neutral-700">
             <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
              <span className="text-green-500">03.</span> Composition
            </h2>
            <div className="flex gap-4 items-center justify-center bg-neutral-900 p-4 rounded-lg">
                <div className="grid grid-cols-3 gap-2">
                    <button className="bg-neutral-700 p-2 rounded hover:bg-neutral-600" onClick={() => adjustPosition(-10, 0, 0)}>←</button>
                    <div className="flex flex-col gap-2">
                         <button className="bg-neutral-700 p-2 rounded hover:bg-neutral-600" onClick={() => adjustPosition(0, -10, 0)}>↑</button>
                         <button className="bg-neutral-700 p-2 rounded hover:bg-neutral-600" onClick={() => adjustPosition(0, 10, 0)}>↓</button>
                    </div>
                    <button className="bg-neutral-700 p-2 rounded hover:bg-neutral-600" onClick={() => adjustPosition(10, 0, 0)}>→</button>
                </div>
                <div className="border-l border-neutral-700 h-16 mx-4"></div>
                <div className="flex flex-col gap-2">
                    <button className="bg-neutral-700 px-4 py-2 rounded hover:bg-neutral-600" onClick={() => adjustPosition(0, 0, 0.1)}>+</button>
                    <Move className="w-6 h-6 text-gray-500 self-center" />
