import React, { useEffect, useRef, forwardRef, useImperativeHandle } from 'react';
import { CardRarity, RapperCardData } from '../types';

interface CardCanvasProps {
  data: RapperCardData;
  width?: number;
  height?: number;
}

export interface CardCanvasHandle {
  download: () => void;
}

const CardCanvas = forwardRef<CardCanvasHandle, CardCanvasProps>(({ data, width = 400, height = 600 }, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  /**
   * Helper to create the specific Shield/Card shape path
   */
  const createCardPath = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    ctx.beginPath();
    const radius = 20;

    // Top Left Corner (Rounded)
    ctx.moveTo(radius, 0);
    ctx.lineTo(w - radius, 0);
    // Top Right Corner
    ctx.quadraticCurveTo(w, 0, w, radius);

    // Right Side to Bottom Point
    ctx.lineTo(w, h * 0.75); // Go down straight-ish for 3/4
    // Shield Curve to tip
    ctx.bezierCurveTo(w, h * 0.9, w * 0.5, h * 0.95, w * 0.5, h); // Curve to bottom center
    ctx.bezierCurveTo(w * 0.5, h * 0.95, 0, h * 0.9, 0, h * 0.75); // Curve from bottom center to left

    // Left Side to Top
    ctx.lineTo(0, radius);
    // Top Left Corner
    ctx.quadraticCurveTo(0, 0, radius, 0);

    ctx.closePath();
  };

  /**
   * Draw the Sunburst/Ray background effect
   */
  const drawBackgroundRays = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    ctx.save();
    // Center of rays roughly behind the character head area
    const cx = w / 2;
    const cy = h * 0.4;
    const maxDist = Math.max(w, h) * 1.5;

    // Dark background base
    ctx.fillStyle = '#050505';
    ctx.fillRect(0, 0, w, h);

    // Draw Rays
    const rays = 24;
    const step = (Math.PI * 2) / rays;

    for (let i = 0; i < rays; i++) {
        const angle = i * step;
        ctx.beginPath();
        ctx.moveTo(cx, cy);

        // Make rays fan out
        const x1 = cx + Math.cos(angle - 0.05) * maxDist;
        const y1 = cy + Math.sin(angle - 0.05) * maxDist;
        const x2 = cx + Math.cos(angle + 0.05) * maxDist;
        const y2 = cy + Math.sin(angle + 0.05) * maxDist;

        ctx.lineTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.closePath();

        // Gradient for rays
        const grad = ctx.createRadialGradient(cx, cy, 10, cx, cy, maxDist);
        grad.addColorStop(0, 'rgba(218, 165, 32, 0.4)'); // Gold center
        grad.addColorStop(1, 'rgba(0, 0, 0, 0)'); // Fade out

        ctx.fillStyle = grad;
        ctx.fill();
    }

    // Add some random sparkles
    for(let i=0; i<30; i++) {
        const x = Math.random() * w;
        const y = Math.random() * h;
        const size = Math.random() * 2;
        ctx.fillStyle = `rgba(255, 215, 0, ${Math.random()})`;
        ctx.beginPath();
        ctx.arc(x, y, size, 0, Math.PI*2);
        ctx.fill();
    }
    ctx.restore();
  };

  const drawCard = async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.clearRect(0, 0, width, height);

    // --- 1. Main Shape Clipping & Background ---
    ctx.save();
    createCardPath(ctx, width, height);
    ctx.clip(); // Restrict all drawing to card shape

    // Draw background rays
    drawBackgroundRays(ctx, width, height);

    // --- 2. Rapper Image ---
    if (data.image) {
      const img = new Image();
      img.src = data.image;
      await new Promise((resolve) => {
        img.onload = resolve;
        img.onerror = resolve; 
      });

      const { x, y, scale } = data.imagePosition;
      const imgW = img.naturalWidth * scale;
      const imgH = img.naturalHeight * scale;
      const centerX = width / 2 + x;
      const centerY = (height * 0.45) + y; // Position slightly higher than center

      // Draw image
      ctx.drawImage(img, centerX - imgW / 2, centerY - imgH / 2, imgW, imgH);
    } else {
        // Placeholder silhouette
        ctx.fillStyle = '#333';
        ctx.beginPath();
        ctx.arc(width/2, height*0.4, 60, 0, Math.PI*2);
        ctx.fill();
        ctx.fillRect(width/2 - 50, height*0.4, 100, 200);
    }

    // --- 3. Bottom Gold Plate (Stats Container) ---
    // This plate usually has a curve at the top
    const plateH = height * 0.35;
    const plateY = height - plateH;

    ctx.beginPath();
    ctx.moveTo(0, plateY);
    // Slight curve up in middle
    ctx.quadraticCurveTo(width/2, plateY - 20, width, plateY);
    ctx.lineTo(width, height);
    ctx.lineTo(0, height);
    ctx.closePath();

    // Gold Gradient for Plate
    const plateGrad = ctx.createLinearGradient(0, plateY, width, height);
    plateGrad.addColorStop(0, '#F3E5AB'); // Light Gold/Cream
    plateGrad.addColorStop(0.2, '#D4AF37'); // Metallic Gold
    plateGrad.addColorStop(0.5, '#F7E7CE'); // Highlight
    plateGrad.addColorStop(0.8, '#C5A028'); // Darker Gold
    plateGrad.addColorStop(1, '#DAA520'); 

    ctx.fillStyle = plateGrad;
    ctx.fill();

    // Add subtle texture/noise to plate (simulated)
    ctx.fillStyle = 'rgba(255,255,255,0.1)';
    ctx.fillRect(0, plateY, width, height-plateY);

    // --- 4. Text & Stats ---

    // NAME
    ctx.fillStyle = '#2a2a2a'; // Dark brown/black for text on gold
    ctx.font = '500 42px Oswald'; // Use Oswald font
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(data.name.toUpperCase(), width / 2, plateY + 50);

    // Underscore line below name (optional decoration)
    // ctx.fillRect(width/2 - 40, plateY + 75, 80, 2);

    // STATS ROW
    // Labels: LYRC, FLOW, SING, LIVE, DISS, CHAR
    const statLabels = [
        { key: 'lyricism', label: 'LYRC' },
        { key: 'flow', label: 'FLOW' },
        { key: 'sing', label: 'SING' },
        { key: 'live', label: 'LIVE' },
        { key: 'diss', label: 'DISS' },
        { key: 'charisma', label: 'CHAR' }
    ];

    const startY = plateY + 95;
    const statSpacing = width / 6.5;
    const startX = width / 2 - (statSpacing * 2.5);

    statLabels.forEach((item, index) => {
        const x = startX + (index * statSpacing);

        // Label
        ctx.font = '700 14px Oswald';
        ctx.fillStyle = '#4a3c1b'; // Dark gold/brown
        ctx.fillText(item.label, x, startY);

        // Value
        ctx.font = '700 24px Oswald';
        ctx.fillStyle = '#1a1a1a'; // Almost black
        const val = data.stats[item.key as keyof typeof data.stats];
        ctx.fillText(val.toString(), x, startY + 30);
    });

    // Icon at bottom
    // Hexagon shape
    const iconY = height - 35;
    const iconSize = 20;
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
        const angle = (Math.PI / 3) * i;
        const ix = width/2 + iconSize * Math.cos(angle);
        const iy = iconY + iconSize * Math.sin(angle);
        if(i===0) ctx.moveTo(ix, iy);
        else ctx.lineTo(ix, iy);
    }
    ctx.closePath();
    ctx.fillStyle = '#111';
    ctx.fill();
    ctx.strokeStyle = '#DAA520';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Inner icon detail
    ctx.fillStyle = '#DAA520';
    ctx.fillRect(width/2 - 5, iconY - 10, 10, 20); // Simple pillar

    ctx.restore(); // End clipping

    // --- 5. Outer Border ---
    // Re-create path to stroke it
    createCardPath(ctx, width, height);

    // Multi-layer border
    ctx.lineWidth = 12;
    // Outer metallic rim
    const borderGrad = ctx.createLinearGradient(0, 0, width, height);
    borderGrad.addColorStop(0, '#FDB931');
    borderGrad.addColorStop(0.25, '#9d7c2a'); // Shadow
    borderGrad.addColorStop(0.5, '#FFFFAC'); // Highlight
    borderGrad.addColorStop(0.75, '#9d7c2a');
    borderGrad.addColorStop(1, '#FDB931');
    ctx.strokeStyle = borderGrad;
    ctx.stroke();

    // Inner thin line
    ctx.lineWidth = 2;
    ctx.strokeStyle = '#000';
    ctx.stroke();

    // --- 6. OVR Rating (Top Left) ---
    // Needs to sit ON TOP of everything
    const ovrX = 65;
    const ovrY = 75;

    // No circle, just large floating number per reference
    ctx.shadowColor = "rgba(0,0,0,0.8)";
    ctx.shadowBlur = 10;
    ctx.fillStyle = '#fff4e0'; // Off white/gold tint
    ctx.font = 'bold 64px Oswald';
    ctx.textAlign = 'center';
    ctx.fillText(data.stats.ovr.toString(), ovrX, ovrY);
    ctx.shadowBlur = 0;
  };

  useEffect(() => {
    drawCard();
  }, [data, width, height]);

  useImperativeHandle(ref, () => ({
    download: () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const link = document.createElement('a');
      link.download = `${data.name.replace(/\s+/g, '_')}_card.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
  }));

  return (
    <div className="relative shadow-2xl rounded-[30px] overflow-hidden" style={{ width, height }}>
      <canvas 
        ref={canvasRef} 
        width={width} 
        height={height} 
        className="bg-transparent"
      />
    </div>
  );
});

CardCanvas.displayName = 'CardCanvas';

