  ovr: 82,
  lyricism: 83,
  flow: 83,
  sing: 82,
  live: 82,
  diss: 78,
  charisma: 82
};

const INITIAL_DATA: RapperCardData = {
  name: "3AB3AZ",
  rarity: CardRarity.GOLD,
  stats: INITIAL_STATS,
  image: null,
  imagePosition: { x: 0, y: 0, scale: 1 },
