                </div>
                <div className="border-l border-neutral-700 h-16 mx-4"></div>
                <div className="flex flex-col gap-2">
                    <button className="bg-neutral-700 px-4 py-2 rounded hover:bg-neutral-600" onClick={() => adjustPosition(0, 0, 0.1)}>+</button>
                    <Move className="w-6 h-6 text-gray-500 self-center" />
                    <button className="bg-neutral-700 px-4 py-2 rounded hover:bg-neutral-600" onClick={() => adjustPosition(0, 0, -0.1)}>-</button>
                </div>
            </div>
            <p className="text-xs text-center text-gray-500 mt-2">Adjust position & scale of the rapper image</p>
          </section>

          {/* 4. Stats */}
           <section className="bg-neutral-800 p-6 rounded-xl border border-neutral-700">
             <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
              <span className="text-red-500">04.</span> Power Stats
            </h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {Object.keys(INITIAL_STATS).map((statKey) => (
                    <div key={statKey}>
                        <label className="block text-xs uppercase text-gray-400 mb-1">{statKey}</label>
                        <input 
                            type="number" 
                            min="0" max="99"
                            value={cardData.stats[statKey as keyof CardStats]} 
                            onChange={(e) => handleStatChange(statKey as keyof CardStats, parseInt(e.target.value))}
                            className="w-full bg-neutral-900 border border-neutral-700 rounded p-2 text-center font-bold font-mono"
                        />
                    </div>
                ))}
            </div>
           </section>

        </div>

        {/* RIGHT COLUMN: Preview */}
        <div className="lg:col-span-5 relative">
            <div className="sticky top-8">
                <h3 className="text-lg font-bold text-gray-400 mb-4 text-center">Live Preview</h3>
                <div className="flex justify-center">
                    <CardCanvas 
                        ref={canvasRef} 
                        data={cardData} 
                        width={400} 
                        height={600} 
                    />
                </div>

                {/* Visual Feedback on Processing */}
                {isProcessing && (
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm rounded-xl flex flex-col items-center justify-center z-10 border border-neutral-600">
                        <div className="animate-spin w-12 h-12 border-4 border-yellow-500 border-t-transparent rounded-full mb-4"></div>
                        <p className="text-yellow-400 font-bold animate-pulse">Consulting the AI...</p>
                    </div>
                )}
            </div>
        </div>
      </main>
    </div>
  );
}

import React, { useEffect, useRef, forwardRef, useImperativeHandle } from 'react';
import { CardRarity, RapperCardData } from '../types';

interface CardCanvasProps {
  data: RapperCardData;
  width?: number;
  height?: number;
}

export interface CardCanvasHandle {
  download: () => void;
}

// Map rarities to the provided image URLs
const RARITY_IMAGES: Record<CardRarity, string> = {
  [CardRarity.GOLD]: 'https://i.imghippo.com/files/tUt8745JBc.png',
  [CardRarity.SILVER]: 'https://i.imghippo.com/files/zC9861peQ.png',
  [CardRarity.BRONZE]: 'https://i.imghippo.com/files/TmM6820WtQ.png',
  [CardRarity.ROTM]: 'https://i.imghippo.com/files/UGRy5126YM.png',
  [CardRarity.ICON]: 'https://i.imghippo.com/files/jdCC2070F.png'
};

const CardCanvas = forwardRef<CardCanvasHandle, CardCanvasProps>(({ data, width = 400, height = 600 }, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  /**
   * Helper to create the specific Shield/Card shape path.
   * We still use this to clip the corners nicely if the loaded image is square.
   */
  const createCardPath = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    ctx.beginPath();
    const radius = 20;

    // Top Left Corner (Rounded)
    ctx.moveTo(radius, 0);
    ctx.lineTo(w - radius, 0);
    // Top Right Corner
    ctx.quadraticCurveTo(w, 0, w, radius);

    // Right Side to Bottom Point
    ctx.lineTo(w, h * 0.75); // Go down straight-ish for 3/4
    // Shield Curve to tip
    ctx.bezierCurveTo(w, h * 0.9, w * 0.5, h * 0.95, w * 0.5, h); // Curve to bottom center
    ctx.bezierCurveTo(w * 0.5, h * 0.95, 0, h * 0.9, 0, h * 0.75); // Curve from bottom center to left

    // Left Side to Top
    ctx.lineTo(0, radius);
    // Top Left Corner
    ctx.quadraticCurveTo(0, 0, radius, 0);

    ctx.closePath();
  };

  const drawCard = async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.clearRect(0, 0, width, height);

    // --- 1. Load Background Template ---
    const bgUrl = RARITY_IMAGES[data.rarity] || RARITY_IMAGES[CardRarity.GOLD];
    const bgImg = new Image();
    bgImg.src = bgUrl;
    bgImg.crossOrigin = "anonymous";

    await new Promise((resolve) => {
      bgImg.onload = resolve;
      bgImg.onerror = resolve; // Just continue if fail, maybe black bg
    });

    // --- 2. Clipping & Composition ---
    ctx.save();

    // Define the shape
    createCardPath(ctx, width, height);
    ctx.clip(); // Restrict all drawing to card shape

    // Draw the template background first
