        { key: 'flow', label: 'FLOW' },
        { key: 'sing', label: 'SING' },
        { key: 'live', label: 'LIVE' },
        { key: 'diss', label: 'DISS' },
        { key: 'charisma', label: 'CHAR' }
    ];

    // Vertical Positions - Moved UP slightly from previous edit
    const labelsY = height * 0.782; 
    const valuesY = height * 0.822; 

    // Horizontal Spacing
    // Spread out significantly to "fill the blue box" area
    const center = width / 2;
    // Steps from center: 25, 75, 125
    const step1 = 25;
    const step2 = 75;
    const step3 = 125;

    const xPositions = [
        center - step3, // LYRC (75px)
        center - step2, // FLOW (125px)
        center - step1, // SING (175px)
        center + step1, // LIVE (225px)
        center + step2, // DISS (275px)
        center + step3  // CHAR (325px)
    ];

