  [CardRarity.GOLD]: 'https://i.imghippo.com/files/tUt8745JBc.png',
  [CardRarity.SILVER]: 'https://i.imghippo.com/files/zC9861peQ.png',
  [CardRarity.BRONZE]: 'https://i.imghippo.com/files/TmM6820WtQ.png',
  [CardRarity.ROTM]: 'https://i.imghippo.com/files/UGRy5126YM.png',
  [CardRarity.ICON]: 'https://i.imghippo.com/files/jdCC2070F.png',
  [CardRarity.ROTY]: 'https://i.imghippo.com/files/PG9297qJ.png',
  [CardRarity.ROTY_ICON]: 'https://i.imghippo.com/files/iwZR6344ujs.png',
  [CardRarity.FIGHTERS]: 'https://res.cloudinary.com/dajbohgkl/image/upload/v1769857631/Gemini_Generated_Image_1thov51thov51tho_1_ppjydc.png',
  [CardRarity.WATN]: 'https://res.cloudinary.com/dajbohgkl/image/upload/v1769867674/Gemini_Generated_Image_ggfslsggfslsggfs_1_yyypqt.png'
};

const LARGE_ICON_IDS = ['showmaker', 'artist', 'story', 'career', 'chopper'];
const EXPORT_SCALE = 3; // 3x Resolution for high quality

const CardCanvas = forwardRef<CardCanvasHandle, CardCanvasProps>(({ data, width = 400, height = 600 }, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  /**
   * Helper to load an image safely.
   */
  const loadImage = (src: string): Promise<HTMLImageElement | null> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = () => {
        console.warn(`Failed to load image: ${src}`);
        resolve(null);
      };
      img.src = src;
    });
  };

  /**
   * Helper to create the outer Card shape path.
   */
  const createCardPath = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    ctx.beginPath();
    const radius = 24;

    // Top Left Corner
    ctx.moveTo(radius, 0);
    ctx.lineTo(w - radius, 0);
    // Top Right Corner
    ctx.quadraticCurveTo(w, 0, w, radius);

    // Right Side to Bottom Point
    ctx.lineTo(w, h * 0.75); 
    // Shield Curve to tip
    ctx.bezierCurveTo(w, h * 0.9, w * 0.5, h * 0.96, w * 0.5, h); 
    ctx.bezierCurveTo(w * 0.5, h * 0.96, 0, h * 0.9, 0, h * 0.75); 

    // Left Side to Top
    ctx.lineTo(0, radius);
    // Top Left Corner
    ctx.quadraticCurveTo(0, 0, radius, 0);

    ctx.closePath();
  };

  const drawCard = async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // --- High DPI Setup ---
    // Reset transform to identity to prevent accumulation
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    // Scale context for high resolution
    ctx.scale(EXPORT_SCALE, EXPORT_SCALE);

    // Clear (using logical dimensions)
    ctx.clearRect(0, 0, width, height);

    // --- Determine Colors based on Rarity ---
    // Default Colors (Gold base)
    let textColorName = '#0a0a0a';       // Black
    let textColorStatsLabel = '#5c4d3c'; // Brown/Gold
    let textColorStatsValue = '#0a0a0a'; // Black
    let textColorOvr = '#F5E6C8';        // Beige/Light Gold

    switch (data.rarity) {
      case CardRarity.BRONZE:
        // Bronze: Name and stats same as OVR
        textColorName = textColorOvr;
        textColorStatsLabel = textColorOvr;
        textColorStatsValue = textColorOvr;
        break;
      case CardRarity.SILVER:
        // Silver: OVR is white
        textColorOvr = '#FFFFFF';
        break;
      case CardRarity.ROTM:
        // ROTM: All text bright cyan
        const cyan = '#00FFFF';
        textColorName = cyan;
        textColorStatsLabel = cyan;
        textColorStatsValue = cyan;
        textColorOvr = cyan;
        break;
      case CardRarity.ICON:
        // Icon: OVR is black
        textColorOvr = '#000000';
        break;
      case CardRarity.ROTY:
         // ROTY: Pure white text
         textColorName = '#FFFFFF';
         textColorStatsLabel = '#FFFFFF';
         textColorStatsValue = '#FFFFFF';
         textColorOvr = '#FFFFFF';
         break;
      case CardRarity.ROTY_ICON:
         // ROTY ICON: All Black text
         textColorName = '#000000';
         textColorStatsLabel = '#000000';
         textColorStatsValue = '#000000';
         textColorOvr = '#000000';
         break;
      case CardRarity.FIGHTERS:
         // FIGHTERS: Light Gold text
         const fightersGold = '#F5E6C8';
         textColorName = fightersGold;
         textColorStatsLabel = fightersGold;
         textColorStatsValue = fightersGold;
         textColorOvr = fightersGold;
         break;
      case CardRarity.WATN:
         // WATN: Gold text
         const watnGold = '#FFD700';
         textColorName = watnGold;
         textColorStatsLabel = watnGold;
         textColorStatsValue = watnGold;
         textColorOvr = watnGold;
         break;
      default:
        // Keeps defaults defined above
        break;
    }

    // --- 1. Load Background Template ---
    const bgUrl = RARITY_IMAGES[data.rarity] || RARITY_IMAGES[CardRarity.GOLD];
    const bgImg = await loadImage(bgUrl);

    // --- 2. Clipping & Composition ---
    ctx.save(); // Save 1: Outer Card Clip

    createCardPath(ctx, width, height);
    ctx.clip(); // Restrict all drawing to card shape

    // Draw the template background first
    if (bgImg) {
       ctx.drawImage(bgImg, 0, 0, width, height);
    } else {
       ctx.fillStyle = '#222';
       ctx.fillRect(0, 0, width, height);
    }

    // --- 3. Rapper Image ---
    if (data.image) {
      const img = await loadImage(data.image);

      if (img) {
        const { x, y, scale } = data.imagePosition;
        const imgW = img.naturalWidth * scale;
        const imgH = img.naturalHeight * scale;
        const centerX = width / 2 + x;
        const centerY = (height * 0.45) + y; 

        ctx.save(); // Save 2: Rapper Clip

        // Define the "Window" where the rapper is visible.
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(width, 0);

        // Define the bottom edge of the rapper visibility (Top edge of the plate)
        const plateSideY = height * 0.62; 
        const plateCenterY = height * 0.65; 

        ctx.lineTo(width, plateSideY);
        // Curve down to center
        ctx.quadraticCurveTo(width / 2, plateCenterY, 0, plateSideY);

        ctx.lineTo(0, 0);
        ctx.closePath();
        ctx.clip();

        // Draw rapper
        ctx.drawImage(img, centerX - imgW / 2, centerY - imgH / 2, imgW, imgH);

        ctx.restore(); // Restore 2
      }
    }

    // --- 4. Superpowers ---
    if (data.superpowers && data.superpowers.length > 0) {
        const iconSize = 55; 
        const xCenter = 40; // Left margin center
        const gap = 8;

        // Calculate vertical centering
        // The available vertical space on the left is roughly from Y=180 to Y=420.
        // Moved down from 280 to 320 to match request
        const containerCenterY = 320;

        // Total height of the stack
        const totalHeight = (data.superpowers.length * iconSize) + ((data.superpowers.length - 1) * gap);

        // Starting Y position to ensure the stack is centered
        let currentY = containerCenterY - (totalHeight / 2);

        for (let i = 0; i < data.superpowers.length; i++) {
            const sp = data.superpowers[i];
            const img = await loadImage(sp.iconUrl);

            if (img) {
                // Aspect Ratio Logic to prevent squishing
                // Fit image within iconSize x iconSize box
                let scale = Math.min(iconSize / img.naturalWidth, iconSize / img.naturalHeight);

                // If it's NOT one of the "naturally big" icons, boost its scale
                if (!LARGE_ICON_IDS.includes(sp.id)) {
                    scale *= 1.25; 
                }

                const w = img.naturalWidth * scale;
                const h = img.naturalHeight * scale;

                // Calculate position to center the image within its specific slot
                // We use iconSize for the slot reference, but draw the image based on its calculated w/h
                // This allows the boosted images to slightly overflow the visual 55px box if needed, 
                // but since they were visually small, they should now look "normal" size.
                const xPos = xCenter - (w / 2);
                const yPos = currentY + (iconSize - h) / 2;

                ctx.save();
                // Draw Icon
                ctx.drawImage(img, xPos, yPos, w, h);
                ctx.restore();

                // Move to next slot
                currentY += iconSize + gap;
            }
        }
    }

    // --- 5. Text & Stats ---

    // NAME
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic'; 
    // Changed to 400 (Regular) weight and moved position down
    // Reduced from 44px by 12.5% -> 38.5px
    ctx.font = '400 38.5px Oswald'; 

    // Position name - Moved DOWN to approx 435px (0.725)
    const nameY = height * 0.725; 

    // Reset shadow defaults first
    ctx.shadowColor = 'transparent';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;

    // Add shadow/glow for specific rarities
    if (data.rarity === CardRarity.ROTY) {
        ctx.shadowColor = 'rgba(0, 0, 0, 0.5)';
        ctx.shadowBlur = 4;
        ctx.shadowOffsetX = 2;
        ctx.shadowOffsetY = 2;
    } else if (data.rarity === CardRarity.ROTY_ICON) {
        // White Outer Glow for ROTY ICON
        ctx.shadowColor = '#FFFFFF';
        ctx.shadowBlur = 50; // Increased even more
        ctx.shadowOffsetX = 0;
        ctx.shadowOffsetY = 0;
    } else if (data.rarity === CardRarity.FIGHTERS) {
        // Dark shadow for Fighters
        ctx.shadowColor = 'rgba(0, 0, 0, 0.7)';
        ctx.shadowBlur = 4;
        ctx.shadowOffsetX = 2;
        ctx.shadowOffsetY = 2;
    } else if (data.rarity === CardRarity.WATN) {
        // Gold Glow for WATN
        ctx.shadowColor = 'rgba(255, 215, 0, 0.5)';
        ctx.shadowBlur = 10;
        ctx.shadowOffsetX = 0;
        ctx.shadowOffsetY = 0;
    }

    ctx.fillStyle = textColorName; 
    ctx.fillText(data.name.toUpperCase(), width / 2, nameY);

    // STATS
    const statLabels = [
        { key: 'lyricism', label: 'LYRC' },
        { key: 'flow', label: 'FLOW' },
        { key: 'sing', label: 'SING' },
        { key: 'live', label: 'LIVE' },
        { key: 'diss', label: 'DISS' },
        { key: 'charisma', label: 'CHAR' }
    ];

    // Vertical Positions - Moved UP slightly on request
    const labelsY = height * 0.77; 
    const valuesY = height * 0.81; 

    // Horizontal Spacing
    // Spread out significantly to "fill the blue box" area
    const center = width / 2;
    // Steps from center: 25, 75, 125
    const step1 = 25;
    const step2 = 75;
    const step3 = 125;

    const xPositions = [
        center - step3, // LYRC (75px)
        center - step2, // FLOW (125px)
        center - step1, // SING (175px)
        center + step1, // LIVE (225px)
        center + step2, // DISS (275px)
        center + step3  // CHAR (325px)
    ];

    statLabels.forEach((item, index) => {
        const x = xPositions[index];

        // Label
        const labelWeight = data.rarity === CardRarity.ROTY_ICON ? '700' : '500';
        ctx.font = `${labelWeight} 12px Oswald`; 
        ctx.fillStyle = textColorStatsLabel;
        ctx.textAlign = 'center';

        if (data.rarity === CardRarity.ROTY_ICON) {
            ctx.lineWidth = 3; // Increased to 3 to be clearly visible
            ctx.strokeStyle = '#FFFFFF';
            ctx.strokeText(item.label, x, labelsY);
        }

        ctx.fillText(item.label, x, labelsY);

        // Value
        const valWeight = data.rarity === CardRarity.ROTY_ICON ? '700' : '400';
        ctx.font = `${valWeight} 22px Oswald`; // Bold for ROTY_ICON, Regular for others
        const valStr = data.stats[item.key as keyof typeof data.stats].toString();
        ctx.fillStyle = textColorStatsValue;
        ctx.fillText(valStr, x, valuesY);
    });

    ctx.restore(); // Restore 1 (Outer Clip)

    // --- 6. OVR Rating (Top Left) ---
    // Moved DOWN more and RIGHT more, reduced size
    const ovrX = 88; 
    const ovrY = 172; 

    ctx.save();
    ctx.font = 'bold 60px Oswald'; // Reduced size slightly
    ctx.textAlign = 'center';

    ctx.fillStyle = textColorOvr;

    // Reset shadow
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;

    if (data.rarity === CardRarity.ROTY_ICON) {
        // White Outer Glow
        ctx.shadowColor = '#FFFFFF';
        ctx.shadowBlur = 50; // Increased even more
    } else if (data.rarity === CardRarity.ROTY) {
        // Standard ROTY Shadow
        ctx.shadowColor = 'rgba(0, 0, 0, 0.5)';
        ctx.shadowBlur = 4;
        ctx.shadowOffsetX = 2;
        ctx.shadowOffsetY = 2;
    } else if (data.rarity === CardRarity.ICON) {
        // No shadow for standard ICON
        ctx.shadowColor = "transparent";
        ctx.shadowBlur = 0;
    } else if (data.rarity === CardRarity.FIGHTERS) {
         // Dark shadow for Fighters
         ctx.shadowColor = 'rgba(0, 0, 0, 0.7)';
         ctx.shadowBlur = 4;
         ctx.shadowOffsetX = 2;
         ctx.shadowOffsetY = 2;
    } else if (data.rarity === CardRarity.WATN) {
         // Gold Glow for WATN
         ctx.shadowColor = 'rgba(255, 215, 0, 0.5)';
         ctx.shadowBlur = 10;
    } else {
        // Default Dark Shadow for Gold, Silver, Bronze, etc.
        ctx.shadowColor = "rgba(0,0,0,0.6)";
        ctx.shadowBlur = 6;
        ctx.shadowOffsetY = 2;
    }

    ctx.fillText(data.stats.ovr.toString(), ovrX, ovrY);

    ctx.restore();
  };

  useEffect(() => {
    drawCard();
  }, [data, width, height]);

  useImperativeHandle(ref, () => ({
    download: () => {
      const canvas = canvasRef.current;
      if (!canvas) return;

      const sanitize = (str: string) => str.trim().replace(/[\s\/\\:*?"<>|]+/g, '_');

      const namePart = sanitize(data.name) || 'Untitled';
      const rarityPart = data.rarity;
      const ovrPart = data.stats.ovr;
      const powersPart = data.superpowers.map(sp => sanitize(sp.name)).join('_');

      let filename = `${namePart}_${rarityPart}_${ovrPart}`;
      if (powersPart) {
        filename += `_${powersPart}`;
      }
      filename += '.webp';

      const link = document.createElement('a');
      link.download = filename;
      link.href = canvas.toDataURL('image/webp');
      link.click();
    }
  }));

  return (
    <div className="relative shadow-2xl rounded-[30px] overflow-hidden" style={{ width, height }}>
      <canvas 
        ref={canvasRef} 
        width={width * EXPORT_SCALE} 
        height={height * EXPORT_SCALE}
        style={{ width, height }} 
        className="bg-transparent"
      />
    </div>
  );
});

CardCanvas.displayName = 'CardCanvas';

export default CardCanvas;

import React, { useState, useRef, ChangeEvent } from 'react';
import { 
  Download, 
  Upload, 
  Sparkles, 
  Wand2, 
  ScanEye, 
  Palette, 
  Move,
  AlertCircle,
  Zap
} from 'lucide-react';
import CardCanvas, { CardCanvasHandle } from './components/CardCanvas';
import { 
  RapperCardData, 
  CardRarity, 
  AspectRatio, 
  ImageSize, 
  CardStats,
  AVAILABLE_SUPERPOWERS,
  SuperPower
} from './types';
import { 
  generateRapperImage, 
  editRapperImage, 
  analyzeRapperImage 
} from './services/geminiService';

const INITIAL_STATS: CardStats = {
  ovr: 82,
  lyricism: 83,
  flow: 83,
  sing: 82,
  live: 82,
  diss: 78,
  charisma: 82
};

const INITIAL_DATA: RapperCardData = {
  name: "3AB3AZ",
  rarity: CardRarity.GOLD,
  stats: INITIAL_STATS,
  image: null,
  imagePosition: { x: 0, y: 0, scale: 1 },
  superpowers: []
};

export default function App() {
  const [cardData, setCardData] = useState<RapperCardData>(INITIAL_DATA);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<'edit' | 'generate' | 'analyze'>('generate');

  // Gemini Inputs
  const [genPrompt, setGenPrompt] = useState("A cool rapper sitting on a chair, wearing blue jersey, sunglasses, digital art style");
  const [genAspectRatio, setGenAspectRatio] = useState<AspectRatio>("3:4");
  const [genSize, setGenSize] = useState<ImageSize>("1K");

  const [editPrompt, setEditPrompt] = useState("Remove the background and add a purple aura");

  const canvasRef = useRef<CardCanvasHandle>(null);

  // Handlers
  const handleInputChange = (field: keyof RapperCardData, value: any) => {
    setCardData(prev => ({ ...prev, [field]: value }));
  };

  const handleStatChange = (stat: keyof CardStats, value: number) => {
    setCardData(prev => ({
      ...prev,
      stats: { ...prev.stats, [stat]: value }
    }));
  };

  const toggleSuperpower = (power: SuperPower) => {
    setCardData(prev => {
      const exists = prev.superpowers.find(p => p.id === power.id);
      if (exists) {
        return {
          ...prev,
          superpowers: prev.superpowers.filter(p => p.id !== power.id)
        };
      } else {
        if (prev.superpowers.length >= 4) return prev;
        return {
          ...prev,
          superpowers: [...prev.superpowers, power]
        };
      }
    });
  };

  const handleImageUpload = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          handleInputChange('image', event.target.result as string);
          // Reset position on new image
          setCardData(prev => ({ ...prev, imagePosition: { x: 0, y: 0, scale: 1 } }));
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateImage = async () => {
    setIsProcessing(true);
    try {
      const b64 = await generateRapperImage(genPrompt, genAspectRatio, genSize);
      handleInputChange('image', b64);
    } catch (e) {
      alert("Failed to generate image. Check console for details.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleEditImage = async () => {
    if (!cardData.image) {
      alert("Upload or generate an image first!");
      return;
    }
    setIsProcessing(true);
    try {
      const b64 = await editRapperImage(cardData.image, editPrompt);
      handleInputChange('image', b64);
    } catch (e) {
      alert("Failed to edit image.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleRemoveBackground = async () => {
    if (!cardData.image) {
      alert("Upload or generate an image first!");
      return;
    }
    setIsProcessing(true);
    try {
      // Use a specific prompt for background removal
      const b64 = await editRapperImage(cardData.image, "Remove the background completely and isolate the subject on a transparent background.");
      handleInputChange('image', b64);
      setEditPrompt("Remove the background"); // Update prompt text to reflect action
    } catch (e) {
      console.error(e);
      alert("Failed to remove background.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAnalyzeImage = async () => {
    if (!cardData.image) {
      alert("Upload or generate an image first!");
      return;
    }
    setIsProcessing(true);
    try {
      const jsonStr = await analyzeRapperImage(cardData.image);
      // Clean JSON string
      const cleanJson = jsonStr.replace(/```json|```/g, '').trim();
      const analysis = JSON.parse(cleanJson);

      // Attempt to map analysis to stats if the AI followed instructions
      if (analysis.stats || analysis.lyricism) {
        // Simplified mapping logic
        const newStats = { ...cardData.stats };
        // Very basic key matching
        Object.keys(analysis).forEach(k => {
            const key = k.toLowerCase();
            if (key.includes('lyr')) newStats.lyricism = Number(analysis[k]) || 80;
            if (key.includes('flow')) newStats.flow = Number(analysis[k]) || 80;
            if (key.includes('sing')) newStats.sing = Number(analysis[k]) || 80;
            if (key.includes('live')) newStats.live = Number(analysis[k]) || 80;
            if (key.includes('diss')) newStats.diss = Number(analysis[k]) || 80;
            if (key.includes('char')) newStats.charisma = Number(analysis[k]) || 80;
        });
        setCardData(prev => ({ ...prev, stats: newStats }));
      } else {
        alert("Analysis Complete: " + JSON.stringify(analysis, null, 2));
      }
    } catch (e) {
      alert("Analysis failed or returned invalid JSON.");
    } finally {
      setIsProcessing(false);
    }
  };

  const adjustPosition = (dx: number, dy: number, dScale: number) => {
    setCardData(prev => ({
      ...prev,
      imagePosition: {
        x: prev.imagePosition.x + dx,
        y: prev.imagePosition.y + dy,
        scale: Math.max(0.1, prev.imagePosition.scale + dScale)
      }
    }));
  };

  return (
    <div className="min-h-screen bg-neutral-900 text-gray-100 p-4 md:p-8">
      <header className="max-w-7xl mx-auto mb-8 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="bg-gradient-to-tr from-yellow-500 to-amber-700 p-2 rounded-lg">
            <Palette className="w-8 h-8 text-white" />
          </div>
          <div>
            <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-yellow-400 to-amber-600">
              RAPPER CARD FORGE
            </h1>
            <p className="text-gray-400 text-sm">Create Legendary Trading Cards</p>
          </div>
        </div>
        <button 
          onClick={() => canvasRef.current?.download()}
          className="flex items-center gap-2 bg-green-600 hover:bg-green-700 px-6 py-3 rounded-full font-bold transition-all shadow-lg hover:shadow-green-500/20"
        >
          <Download className="w-5 h-5" />
          Download Card
        </button>
      </header>

      <main className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* LEFT COLUMN: Controls */}
        <div className="lg:col-span-7 space-y-6">

          {/* 1. Card Identity */}
          <section className="bg-neutral-800 p-6 rounded-xl border border-neutral-700">
            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
              <span className="text-yellow-500">01.</span> Identity & Base
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm text-gray-400 mb-1">Rapper Name</label>
                <input 
                  type="text" 
                  value={cardData.name}
                  onChange={(e) => handleInputChange('name', e.target.value)}
                  className="w-full bg-neutral-900 border border-neutral-700 rounded p-2 focus:border-yellow-500 outline-none transition-colors"
                />
              </div>
              <div>
                <label className="block text-sm text-gray-400 mb-1">Rarity</label>
                <select 
                  value={cardData.rarity}
                  onChange={(e) => handleInputChange('rarity', e.target.value)}
                  className="w-full bg-neutral-900 border border-neutral-700 rounded p-2 outline-none"
                >
                  {Object.values(CardRarity).map(r => (
                    <option key={r} value={r}>{r}</option>
                  ))}
                </select>
              </div>
            </div>
          </section>

          {/* 2. AI & Image Tools */}
          <section className="bg-neutral-800 p-6 rounded-xl border border-neutral-700">
            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
              <span className="text-blue-500">02.</span> Visual Studio
            </h2>

            <div className="flex gap-2 mb-4 bg-neutral-900 p-1 rounded-lg w-fit">
              <button 
                onClick={() => setActiveTab('generate')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'generate' ? 'bg-neutral-700 text-white' : 'text-gray-400 hover:text-white'}`}
              >
                <Sparkles className="w-4 h-4" /> Generate
              </button>
              <button 
                onClick={() => setActiveTab('edit')}
