                    <div className="flex-1">
                       <label className="block text-xs text-gray-500 mb-1">Quality</label>
                       <select value={genSize} onChange={e => setGenSize(e.target.value as ImageSize)} className="w-full bg-neutral-900 border border-neutral-700 p-2 rounded">
