                   <div className="bg-neutral-900 p-3 rounded-lg border border-neutral-700">
                      <p className="text-xs font-bold text-gray-400 mb-2 uppercase tracking-wider">Quick Actions</p>
                      <button 
                        onClick={handleRemoveBackground}
                        disabled={isProcessing || !cardData.image}
                        className="flex items-center gap-2 w-full justify-center bg-neutral-800 hover:bg-neutral-700 border border-neutral-600 text-white py-2 rounded text-sm transition-colors disabled:opacity-50"
                      >
                        <Zap className="w-4 h-4 text-yellow-400" />
